    GSTRate = apps.get_model('shop', 'GSTRate')
    GSTConfig = apps.get_model('shop', 'GSTConfig')
    default_rate = None
    for pct in ('0.00', '5.00', '12.00', '18.00', '28.00'):
        label = f"GST {pct.rstrip('0').rstrip('.')}%"
        rate, _ = GSTRate.objects.get_or_create(
            percentage=pct,
            defaults={'name': label, 'is_active': True},
        )
        if pct == '18.00':
            default_rate = rate
    if default_rate is None:
        default_rate = GSTRate.objects.first()
    GSTConfig.objects.get_or_create(pk=1, defaults={'default_rate': default_rate})


